 return c and c['n']>=200 and c['days']>=20 and c['metrics']['delta_logloss']['mean']<0 and c['metrics']['delta_brier']['mean']<=0 and (not cal or (c['metrics']['delta_cal_logloss']['mean']<0 and c['metrics']['delta_cal_brier']['mean']<=0))
def robust(c,field):
 return c and c['metrics'][field]['adjusted_p']<.05 and c['week'][field]['adjusted_p']<.05
allcells=[];globalrows=[];inv=[]
for (s,i),d in reports.items():
 globalrows.append(dict(stage=s,method=i,name=d['name'],rows=d['rows'],contracts=d['markets'],**d['means'],**{k:v['mean'] for k,v in d['metrics'].items()}))
 for c in d['cells']:
