  allcells.append(row)
for lead,b in itertools.product([2,5,8,11,14],range(10)):
 bin_=f'{b*10:02d}-{(b+1)*10}'
 ws=lookup.get(('warmup',1,lead,bin_));vs=lookup.get(('validation',1,lead,bin_))
 wselected=[i for i in range(1,21) if (i,lead,bin_) in keys]
 raw=[i for i in range(1,21) if support(lookup.get(('warmup',i,lead,bin_))) and support(lookup.get(('validation',i,lead,bin_)))]
 cal=[i for i in raw if support(lookup.get(('warmup',i,lead,bin_)),True) and support(lookup.get(('validation',i,lead,bin_)),True)]
 surviving=[i for i in wselected if i in cal]
 best=min(wselected,key=lambda i:lookup['warmup',i,lead,bin_]['metrics']['delta_cal_logloss']['mean']) if wselected else None
 bc=lookup.get(('validation',best,lead,bin_))
 row={'asset':'BTC','lead_minutes':lead,'probability_bin':bin_,'warmup_n':ws['n'] if ws else 0,'validation_n':vs['n'] if vs else 0,'warmup_days':ws['days'] if ws else 0,'validation_days':vs['days'] if vs else 0,'warmup_selected_methods':';'.join(map(str,wselected)),'two_period_raw_support_methods':';'.join(map(str,raw)),'two_period_calibration_support_methods':';'.join(map(str,cal)),'selected_survivors':';'.join(map(str,surviving)),'warmup_best_selected_method':best,'warmup_best_validation_delta_logloss':bc['metrics']['delta_logloss']['mean'] if bc else None,'warmup_best_validation_delta_cal_logloss':bc['metrics']['delta_cal_logloss']['mean'] if bc else None}
