"""Execute sealed JSONs, attest outputs, and summarize all50cells."""
import datetime,hashlib,json,os,subprocess,sys
from pathlib import Path
import numpy as np
import pandas as pd
from scipy.stats import t
from build_config import ROOT,BASE,OUT
from dskit.pipeline.document import load_document
from dskit.pipeline.driver import RunAttestation
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def stat(g,field,cluster='day',family=1000):
 a=g[field].to_numpy(float);mu=float(a.mean())
 residual=pd.DataFrame({'g':g[cluster].to_numpy(),'r':a-mu}).groupby('g').r.sum()
 k=len(residual);se=float(np.sqrt(k/(k-1)*(residual**2).sum())/len(a)) if k>1 else None
 p=float(t.cdf(mu/se,k-1)) if se and se>0 else 1.
 return dict(mean=mu,se=se,p=p,adjusted_p=min(1.,p*family),n=len(a),clusters=k)
def summarize(i,stage,path,run):
 doc=load_document(str(path));att=RunAttestation(str(run))
 assert att.completed() and att.binds_document_identity(doc.hash)
 carry=json.load(open(run/'carry.json'));outputs={}
 for view in ['predictions','markets','cells','leads','asset_leads','calibration']:
  key='write_'+view;p=Path(att.attested_output(key,'path',doc.hash))
  assert sha(p)==carry[key]['metrics']['sha256']
  outputs[view]={'path':str(p),'sha256':sha(p),'rows':carry[key]['metrics']['rows']}
 df=pd.read_json(outputs['predictions']['path'],lines=True,precise_float=True)
 mk=pd.read_json(outputs['markets']['path'],lines=True,precise_float=True)
 for tab in [df,mk]:tab['week']=pd.to_datetime(tab.day).astype('int64')//(7*86400*10**9)
 fields=['delta_logloss','delta_brier','delta_cal_logloss','delta_cal_brier']
 means=['mid','prediction','label','cal_market','model_logloss','market_logloss','cal_logloss','model_brier','market_brier','cal_brier']
 cells=[]
 for (lead,bin_),g in df.groupby(['lead_minutes','probability_bin']):
  cells.append(dict(asset='BTC',lead=int(lead),bin=bin_,n=len(g),days=g.day.nunique(),metrics={f:stat(g,f) for f in fields},week={f:stat(g,f,'week') for f in fields},means={k:float(g[k].mean()) for k in means}))
 sensitivity={}
 for tag,mask in [('age_le30',df.age_s<=30),('age31_60',df.age_s.between(31,60)),('age_gt60',df.age_s>60),('nonextreme',df.mid.between(.1,.9))]:
  g=df[mask]
  sensitivity[tag]={'n':len(g),'metrics':{f:stat(g,f,family=20) for f in fields}} if len(g) else {'n':0}
 result=dict(method=i,stage=stage,name=path.stem.split(f'-{i:02d}-',1)[1],config=str(path.relative_to(ROOT)),config_sha256=sha(path),document_hash=doc.hash,run=str(run),outputs=outputs,metrics={f:stat(mk,f,family=20) for f in fields},week={f:stat(mk,f,'week',20) for f in fields},means={k:float(mk[k].mean()) for k in means},cells=cells,rows=len(df),markets=len(mk),days=int(df.day.nunique()),sensitivity=sensitivity,row_identity=hashlib.sha256(df[['ticker','lead_minutes']].sort_values(['ticker','lead_minutes']).to_csv(index=False).encode()).hexdigest())
 (OUT/f'{stage}-{i:02d}.json').write_text(json.dumps(result,indent=2)+'\n')
 return result
def main(stage,ids):
 if stage=='validation':
  lock=json.load(open(OUT/'selection-lock.json'))
  for rel,h in lock['configs'].items():assert sha(ROOT/rel)==h
  for rel,h in lock['warmup'].items():assert sha(OUT/rel)==h
 for i in ids:
  if (OUT/f'{stage}-{i:02d}.json').exists():print(stage,i,'complete',flush=True);continue
  path=next((BASE/'configs').glob(f'run-polymarket20-{stage}-{i:02d}-*.json'))
  cfg=json.load(open(path));doc=load_document(str(path))
  run=Path(cfg['outputs']['run_root'])/(cfg['name']+'-2026-10-18-'+doc.hash[:8])
  entry={'stage':stage,'method':i,'start':datetime.datetime.now(datetime.timezone.utc).isoformat(),'config_sha256':sha(path),'rationale':cfg['notes']}
  with (OUT/'iterations.jsonl').open('a') as f:f.write(json.dumps(entry)+'\n')
  with (OUT/f'{stage}-{i:02d}.log').open('w') as log:
   env={**os.environ,'PYTHONPATH':str(ROOT),'OMP_NUM_THREADS':'2','OPENBLAS_NUM_THREADS':'2','MKL_NUM_THREADS':'2'}
   p=subprocess.run([sys.executable,'-m','dskit.pipeline','run',str(path),'--asof','2026-10-18'],cwd=BASE,env=env,stdout=log,stderr=subprocess.STDOUT)
  if p.returncode:raise RuntimeError((OUT/f'{stage}-{i:02d}.log').read_text()[-2500:])

  if not run.exists():
   candidates=list(Path(cfg['outputs']['run_root']).glob(cfg['name']+'-*'))
   candidates=[x for x in candidates if RunAttestation(str(x)).completed()]
   assert len(candidates)==1;run=candidates[0]
  r=summarize(i,stage,path,run)
  print(stage,i,r['name'],'LLraw',round(r['metrics']['delta_logloss']['mean'],7),'LLcal',round(r['metrics']['delta_cal_logloss']['mean'],7),flush=True)
if __name__=='__main__':main(sys.argv[1],list(map(int,sys.argv[2:])) or range(1,21))

