  assert sum(int(r[stage+'_n']) for r in rows)==report['rows']

def test_support_and_survivors_cover_every_native_cell():
 rows=list(csv.DictReader(open(MEMO/'2026-10-18-polymarket-predictability-inventory.csv')))
 inventory={(int(r['lead_minutes']),r['probability_bin']):r for r in rows}
 expectedraw={};expectedsurv={}
 selected={(x['method'],x['lead'],x['bin']) for x in json.load(open(OUT/'selection-lock.json'))['selected']}
 def wins(c,fields):
  return c['n']>=200 and c['days']>=20 and c['metrics'][fields[0]]['mean']<0 and c['metrics'][fields[1]]['mean']<=0
 for i in range(1,21):
